          }
          if (value.data2 != 0) {
            ProtoAdapter.UINT32.encodeWithTag(writer, 4, value.data2)
          }
          if (value.data1 != "") {
            ProtoAdapter.STRING.encodeWithTag(writer, 3, value.data1)
          }
          if (value.id1 != "") {
            ProtoAdapter.STRING.encodeWithTag(writer, 1, value.id1)
          }
        }

        override fun decode(reader: ProtoReader): LiveShoppingDetails {
          var id1: String = ""
          var data1: String = ""
          var data2: Int = 0
          var timestamp: Long = 0L
          var data_: ValueLabel? = null
          val unknownFields = reader.forEachTag { tag ->
            when (tag) {
              1 -> id1 = ProtoAdapter.STRING.decode(reader)
              3 -> data1 = ProtoAdapter.STRING.decode(reader)
              4 -> data2 = ProtoAdapter.UINT32.decode(reader)
              5 -> timestamp = ProtoAdapter.UINT64.decode(reader)
              6 -> data_ = ValueLabel.ADAPTER.decode(reader)
              else -> reader.readUnknownField(tag)
            }
          }
          return LiveShoppingDetails(
            id1 = id1,
            data1 = data1,
            data2 = data2,
            timestamp = timestamp,
            data_ = data_,
            unknownFields = unknownFields
          )
        }

        override fun redact(`value`: LiveShoppingDetails): LiveShoppingDetails = value.copy(
          data_ = value.data_?.let(ValueLabel.ADAPTER::redact),
          unknownFields = ByteString.EMPTY
        )
      }

      private const val serialVersionUID: Long = 0L
    }
  }
